/**
 * Slack interactive payloads (Block Kit clicks), from Socket Mode or, on
 * hosted v2, from the control plane's interactivity route.
 *
 * Built-in tool-approval Approve/Deny actions resolve parked calls
 * ({@link dispatchInteractiveFromPayload}, Socket Mode only); everything
 * else can be routed to an author handler ({@link dispatchBlockAction} via
 * `slackChannel({ onBlockAction })`).
 */
import { slackDmScopeFor, } from "../../internal/continuation-identity.js";
import { isRecord } from "../../internal/is-record.js";
import { slackDmIsOneSession } from "../../internal/slack-thread-key.js";
import { updateMessage } from "./api.js";
import { decisionFromActionId, decisionFromAuthActionId, parseApprovalActionValue, } from "./approvals.js";
import { buildSlackInteractiveApprovalAuth } from "./auth.js";
import { dispatchInboundMessage } from "./dispatch.js";
import { isExternalSlackSender } from "./external-policy.js";
import { defaultSlackLog } from "./log.js";
/**
 * Handle a Socket Mode `interactive` body. Returns true when this was
 * an agent-serve approval action (handled or rejected with a reason).
 */
export async function dispatchInteractiveFromPayload(payload, deps) {
    const log = deps.log ?? defaultSlackLog;
    const parsed = parseSlackBlockAction(payload);
    if (parsed === null) {
        return false;
    }
    const approvalDecision = decisionFromActionId(parsed.actionId);
    const authDecision = decisionFromAuthActionId(parsed.actionId);
    const value = parseApprovalActionValue(parsed.value);
    if (value === null || (approvalDecision === null && authDecision === null)) {
        return false;
    }
    const decision = approvalDecision ?? authDecision;
    if (decision === null) {
        return false;
    }
    const kind = approvalDecision !== null ? "approval" : "auth";
    log.info("interactive approval", {
        decision,
        session: value.sessionId,
        call_id: value.callId,
        user: parsed.userId,
        channel: parsed.channelId,
    });
    const session = await deps.getSession(value.sessionId);
    if (session === null) {
        log.warn("interactive approval: unknown session", {
            session: value.sessionId,
        });
        return true;
    }
    const attrs = session.info.auth?.attributes ?? {};
    const sessionChannel = attrs.channel_id ?? "";
    const sessionThread = attrs.thread_ts ?? "";
    if (sessionChannel !== "" && parsed.channelId !== "" && sessionChannel !== parsed.channelId) {
        log.warn("interactive approval: channel mismatch", {
            session: value.sessionId,
            expected: sessionChannel,
            got: parsed.channelId,
        });
        return true;
    }
    if (!slackDmIsOneSession(parsed.channelId, slackDmScopeFor(deps.continuation)) &&
        sessionThread !== "" &&
        parsed.threadTs !== "" &&
        sessionThread !== parsed.threadTs) {
        log.warn("interactive approval: thread mismatch", {
            session: value.sessionId,
            expected: sessionThread,
            got: parsed.threadTs,
        });
        return true;
    }
    const sessionAuth = session.info.auth;
    if (sessionAuth === undefined || sessionAuth === null) {
        log.warn("interactive approval: session has no auth", {
            session: value.sessionId,
        });
        return true;
    }
    const teamId = attrs.team_id;
    if (deps.blockExternals !== false && parsed.userId !== "") {
        if (teamId === undefined || teamId === "") {
            log.info("interactive approval dropped (missing team)", {
                session: value.sessionId,
                user: parsed.userId,
            });
            return true;
        }
        if (await isExternalSlackSender({
            botToken: deps.credentials?.botToken,
            slackTeamId: teamId,
            userId: parsed.userId,
        })) {
            log.info("interactive approval dropped (external sender)", {
                session: value.sessionId,
                user: parsed.userId,
                team: teamId,
            });
            return true;
        }
    }
    const clickingAuth = buildSlackInteractiveApprovalAuth({
        sessionAuth,
        channelId: parsed.channelId || sessionChannel,
        threadTs: parsed.threadTs || sessionThread,
        teamId: teamId === undefined || teamId === "" ? undefined : teamId,
        clickingUserId: parsed.userId,
    });
    try {
        if (kind === "auth") {
            await deps.resolveAuth(value.sessionId, value.callId, decision, clickingAuth);
        }
        else {
            await deps.resolveApproval(value.sessionId, value.callId, decision, clickingAuth);
        }
    }
    catch (error) {
        log.warn("interactive approval resolve failed", {
            session: value.sessionId,
            call_id: value.callId,
            error: error instanceof Error ? error.message : String(error),
        });
    }
    return true;
}
/**
 * Parse a Socket Mode `block_actions` payload into a {@link SlackBlockAction}.
 * Returns null for non-`block_actions` payloads (view submissions, shortcuts)
 * and malformed bodies.
 */
export function parseSlackBlockAction(payload) {
    if (!isRecord(payload)) {
        return null;
    }
    const record = payload;
    if (record.type !== "block_actions") {
        return null;
    }
    const actions = record.actions;
    if (!Array.isArray(actions) || actions.length === 0) {
        return null;
    }
    const first = actions[0];
    if (!isRecord(first)) {
        return null;
    }
    const action = first;
    if (typeof action.action_id !== "string") {
        return null;
    }
    const channel = isRecord(record.channel) ? record.channel : {};
    const message = isRecord(record.message) ? record.message : {};
    const user = isRecord(record.user) ? record.user : {};
    const team = isRecord(record.team) ? record.team : {};
    const container = isRecord(record.container) ? record.container : undefined;
    const channelId = typeof channel.id === "string" ? channel.id : "";
    const messageTs = typeof message.ts === "string" ? message.ts : "";
    const threadTs = typeof message.thread_ts === "string"
        ? message.thread_ts
        : typeof container?.thread_ts === "string"
            ? container.thread_ts
            : messageTs;
    const userId = typeof user.id === "string" ? user.id : "";
    const userName = typeof user.username === "string"
        ? user.username
        : typeof user.name === "string"
            ? user.name
            : undefined;
    // Payload `team.id` only — never `user.team_id` (Connect home team).
    // Membership gates must baseline the install workspace separately.
    const teamId = typeof team.id === "string" ? team.id : undefined;
    const actionText = isRecord(action.text) ? action.text : undefined;
    const label = typeof actionText?.text === "string" ? actionText.text : undefined;
    const actionTs = typeof action.action_ts === "string" ? action.action_ts : "";
    const messageBlocks = Array.isArray(message.blocks) ? message.blocks : undefined;
    return {
        actionId: action.action_id,
        blockId: typeof action.block_id === "string" ? action.block_id : "",
        value: typeof action.value === "string" ? action.value : "",
        label,
        channelId,
        threadTs,
        messageTs,
        messageBlocks,
        userId,
        userName,
        teamId,
        actionTs,
    };
}
/**
 * Swap the clicked message's actions row for a context note (`chat.update`).
 * Strips only the row the click came from (`action.blockId`); every other
 * block survives. Soft: false when the payload carried no message blocks or
 * the update failed — callers treat the dispatched turn as the durable
 * record and the card as best-effort UI.
 */
export async function resolveBlockActionCard(args) {
    const { action, note } = args;
    if (action.messageBlocks === undefined) {
        return false;
    }
    const clicked = (block) => typeof block === "object" &&
        block !== null &&
        block.type === "actions" &&
        block.block_id === action.blockId;
    const result = await updateMessage({
        botToken: args.botToken,
        channel: action.channelId,
        ts: action.messageTs,
        text: note,
        blocks: [
            ...action.messageBlocks.filter((block) => !clicked(block)),
            { type: "context", elements: [{ type: "mrkdwn", text: note }] },
        ],
    });
    return result.ok;
}
/**
 * The click as an inbound-message stand-in: the synthetic ts is the click's
 * `action_ts` (unique per click, never a real thread message), so ask-dedupe
 * claims and `<slack_thread>` exclusions stay per-click.
 */
function blockActionAsMessage(action, installTeamId) {
    const text = `[clicked: ${action.label ?? action.actionId}]`;
    return {
        text,
        body: text,
        markdown: text,
        ts: action.actionTs,
        threadTs: action.threadTs,
        channelId: action.channelId,
        teamId: installTeamId,
        author: {
            userId: action.userId,
            userName: action.userName,
            isBot: false,
        },
    };
}
/**
 * Route a non-approval `block_actions` payload to the author handler and
 * dispatch its decision as a turn on the click's thread. Returns true when
 * the payload was a block action (dispatched or deliberately skipped).
 */
export async function dispatchBlockAction(payload, deps) {
    const log = deps.log ?? defaultSlackLog;
    const action = parseSlackBlockAction(payload);
    if (action === null) {
        return false;
    }
    if (action.channelId === "" || action.threadTs === "") {
        log.warn("block action skipped (no conversation)", {
            action_id: action.actionId,
            user: action.userId,
        });
        return true;
    }
    // Slack stamps every real click; without one the synthetic message ts
    // would alias another click's dedupe claim.
    if (action.actionTs === "") {
        log.warn("block action skipped (no action_ts)", {
            action_id: action.actionId,
            user: action.userId,
        });
        return true;
    }
    log.info("block action", {
        action_id: action.actionId,
        channel: action.channelId,
        thread_ts: action.threadTs,
        message_ts: action.messageTs,
        user: action.userId,
    });
    await dispatchInboundMessage({
        kind: "block_action",
        message: blockActionAsMessage(action, deps.installTeamId),
        handler: (ctx) => deps.handler(ctx, action),
        send: deps.send,
        authPrompts: deps.authPrompts,
        credentials: deps.credentials,
        host: deps.host,
        artifacts: deps.artifacts,
        log,
        // Click text is synthetic — never treat it as a stop/eval directive.
        evalCommandsEnabled: false,
        blockExternals: deps.blockExternals,
        propagateHandlerErrors: deps.propagateHandlerErrors,
        hasContinuationSession: deps.hasContinuationSession,
        isContinuationBusy: deps.isContinuationBusy,
        getContinuationLastBotMessageTs: deps.getContinuationLastBotMessageTs,
        interruptContinuation: deps.interruptContinuation,
        ...(deps.continuation === undefined ? {} : { continuation: deps.continuation }),
    });
    return true;
}
